import 'wellness_action.dart';

/// A personalized, time-bounded set of wellness actions generated by the
/// AI Engine for a specific user on a specific calendar day.
///
/// The [totalTime] field must always equal the sum of all
/// [WellnessAction.durationMinutes] in [actions]. This invariant is
/// enforced in the constructor assertion and recalculated in [fromMap].
class DailyPlan {
  final String id;
  final DateTime date;
  final String todaysFocus;
  final List<WellnessAction> actions;
  final int totalTime;
  final String? aiInsight;
  final bool isFallback;
  final bool isCompleted;
  final String? checkInId;
  final int? energyTier;

  DailyPlan({
    required this.id,
    required this.date,
    required this.todaysFocus,
    required this.actions,
    required this.totalTime,
    this.aiInsight,
    this.isFallback = false,
    this.isCompleted = false,
    this.checkInId,
    this.energyTier,
  }) : assert(
          totalTime == actions.fold<int>(0, (sum, a) => sum + a.durationMinutes),
          'totalTime must equal the sum of action.durationMinutes',
        );

  /// Number of actions the user has completed.
  int get completedActionsCount =>
      actions.where((a) => a.isCompleted).length;

  /// Whether every action in the plan has been completed.
  bool get allActionsCompleted =>
      completedActionsCount == actions.length && actions.isNotEmpty;

  Map<String, dynamic> toMap() {
    return {
      'id': id,
      'date': date.toIso8601String(),
      'todaysFocus': todaysFocus,
      'actions': actions.map((a) => a.toMap()).toList(),
      'totalTime': totalTime,
      'aiInsight': aiInsight,
      'isFallback': isFallback,
      'isCompleted': isCompleted,
      'checkInId': checkInId,
      'energyTier': energyTier,
    };
  }

  factory DailyPlan.fromMap(Map<String, dynamic> map) {
    final actions = (map['actions'] as List<dynamic>)
        .map((a) => WellnessAction.fromMap(a as Map<String, dynamic>))
        .toList();

    final calculatedTotalTime =
        actions.fold<int>(0, (sum, a) => sum + a.durationMinutes);

    return DailyPlan(
      id: map['id'] as String,
      date: DateTime.parse(map['date'] as String),
      todaysFocus: map['todaysFocus'] as String,
      actions: actions,
      totalTime: calculatedTotalTime,
      aiInsight: map['aiInsight'] as String?,
      isFallback: map['isFallback'] as bool? ?? false,
      isCompleted: map['isCompleted'] as bool? ?? false,
      checkInId: map['checkInId'] as String?,
      energyTier: map['energyTier'] as int?,
    );
  }

  DailyPlan copyWith({
    String? id,
    DateTime? date,
    String? todaysFocus,
    List<WellnessAction>? actions,
    int? totalTime,
    String? aiInsight,
    bool? isFallback,
    bool? isCompleted,
    String? checkInId,
    int? energyTier,
  }) {
    final newActions = actions ?? this.actions;
    final newTotalTime =
        totalTime ?? newActions.fold<int>(0, (sum, a) => sum + a.durationMinutes);

    return DailyPlan(
      id: id ?? this.id,
      date: date ?? this.date,
      todaysFocus: todaysFocus ?? this.todaysFocus,
      actions: newActions,
      totalTime: newTotalTime,
      aiInsight: aiInsight ?? this.aiInsight,
      isFallback: isFallback ?? this.isFallback,
      isCompleted: isCompleted ?? this.isCompleted,
      checkInId: checkInId ?? this.checkInId,
      energyTier: energyTier ?? this.energyTier,
    );
  }
}
